{"file_path":"simple_linked_list.go","content":"package linkedlist

import "errors"

// Element is a single node in a singly linked list.
type Element struct {
	value int
	next  *Element
}

// List is a singly linked list of int values.
type List struct {
	head *Element
	size int
}

func New(elements []int) *List {
	l := &List{}
	for _, e := range elements {
		l.Push(e)
	}
	return l
}

func (l *List) Size() int {
	return l.size
}

func (l *List) Push(element int) {
	l.head = &Element{value: element, next: l.head}
	l.size++
}

func (l *List) Pop() (int, error) {
	if l.head == nil {
		return 0, errors.New("pop from empty list")
	}
	value := l.head.value
	l.head = l.head.next
	l.size--
	return value, nil
}

func (l *List) Array() []int {
	array := make([]int, l.size)
	e := l.head
	for i := l.size - 1; i >= 0; i-- {
		array[i] = e.value
		e = e.next
	}
	return array
}

func (l *List) Reverse() *List {
	reversed := &List{}
	e := l.head
	for e != nil {
		reversed.Push(e.value)
		e = e.next
	}
	return reversed
}
"}

